import sys
from collections import deque, defaultdict

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    try:
        N = int(next(iterator))
        P = int(next(iterator))
    except StopIteration:
        return

    graph = defaultdict(list)
    in_degree = [0] * N

    for _ in range(P):
        u = int(next(iterator))
        v = int(next(iterator))
        graph[v].append(u)
        in_degree[u] += 1

    queue = deque()
    for i in range(N):
        if in_degree[i] == 0:
            queue.append(i)

    count = 0
    while queue:
        node = queue.popleft()
        count += 1
        for neighbor in graph[node]:
            in_degree[neighbor] -= 1
            if in_degree[neighbor] == 0:
                queue.append(neighbor)

    if count == N:
        print("Yes")
    else:
        print("No")

if __name__ == "__main__":
    main()
